#!/usr/bin/env bash
#
# Delete remote branches whose heads belong to closed pull requests.
#
# Usage:
#   ./scripts/delete-closed-pr-branches.sh              # dry run
#   ./scripts/delete-closed-pr-branches.sh --apply      # actually delete
#
# Requirements:
#   - git remote "origin" points at the target repo
#   - the credentials used by git push must have permission to delete branches
#     (GitHub personal access token with "repo" scope, or SSH key with write
#     access). The http proxy used by the Claude Code sandbox will not work --
#     run this from a regular shell.
#
# Generated by auditing closed PRs on 2026-04-20 against the existing branch
# list. Orphan branches (no PR) and active branches are intentionally excluded:
#   - main
#   - claude/cleanup-closed-pr-branches-R7WBj
#   - claude/issue-3-dashboard-impl
#   - claude/issue-3-dashboard-v3
#   - claude/serene-gauss-issue-3-dashboard
#   - feature/serene-gauss-ticket-3-dashboard

set -euo pipefail

APPLY=0
if [[ "${1:-}" == "--apply" ]]; then
  APPLY=1
fi

BRANCHES=(
  claude/7EEVS-issue-10-quick-actions
  claude/7EEVS-issue-3-dashboard
