echo "Branches to delete: ${#BRANCHES[@]}"

if [[ $APPLY -eq 0 ]]; then
  echo "(dry run -- re-run with --apply to delete)"
  printf '  %s\n' "${BRANCHES[@]}"
  exit 0
fi

for i in $(seq 0 30 $((${#BRANCHES[@]} - 1))); do
  batch=("${BRANCHES[@]:$i:30}")
  echo "Deleting batch starting at index $i (${#batch[@]} branches)..."
  git push origin --delete "${batch[@]}"
done

echo "Done."
